import express from "express";
import { supabase } from "../lib/supabase.js";
import { logger } from "../lib/logger.js";
import {
  Sep0001ConfigError,
  generateStellarTomlReport,
  validateStellarToml,
} from "../lib/sep0001-generator.js";
import { recordSep0001Request } from "../lib/sep0001-telemetry.js";

const router = express.Router();

// Any RFC 4122 UUID (merchant ids are generated by Postgres).
const MERCHANT_ID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

/**
 * Resolve and strictly validate the merchant id (issue #1457).
 * @returns {{ merchantId?: string, error?: string }}
 */
export function resolveMerchantId(req) {
  const fromQuery = req.query.merchant_id;
  if (fromQuery !== undefined) {
    if (typeof fromQuery !== "string") {
      return { error: "merchant_id must be a single value" };
    }
    if (!MERCHANT_ID_PATTERN.test(fromQuery)) {
      return { error: "merchant_id must be a valid UUID" };
    }
    return { merchantId: fromQuery };
  }

  // If no merchant_id provided, use authenticated merchant
  if (req.merchant?.id) return { merchantId: String(req.merchant.id) };

  return { error: "merchant_id required" };
}

/**
 * @swagger
 * /.well-known/stellar.toml:
 *   get:
 *     summary: Get SEP-0001 stellar.toml for merchant
 *     tags: [SEP-0001]
 *     parameters:
 *       - in: query
 *         name: merchant_id
 *         schema:
 *           type: string
 *           format: uuid
 *         description: Merchant ID (optional, uses authenticated merchant if not provided)
 *     responses:
 *       200:
 *         description: SEP-0001 stellar.toml content
 *         content:
 *           text/plain:
 *             schema:
 *               type: string
 *       400:
 *         description: merchant_id missing, repeated or not a UUID
 *       404:
 *         description: Merchant not found
 *       500:
 *         description: Failed to generate stellar.toml
 *       503:
 *         description: >
 *           Merchant lookup kept failing with a transient error after
 *           automatic retries with exponential backoff (issue #1459).
 *           Includes a Retry-After header; never cached.
 */
router.get("/.well-known/stellar.toml", async (req, res, next) => {
  const startedAt = process.hrtime.bigint();
  let rejections = [];
  const finish = (outcome, documentBytes) =>
    recordSep0001Request({
      outcome,
      durationSeconds: Number(process.hrtime.bigint() - startedAt) / 1e9,
      documentBytes,
      rejections,
    });

  let merchantId;
  try {
    const resolved = resolveMerchantId(req);
    if (resolved.error) {
      finish("invalid_request");
      return res.status(400).json({ error: resolved.error });
    }
    merchantId = resolved.merchantId;

    // Fetch merchant data, retrying transient failures with exponential
    // backoff (issue #1459). Deterministic errors come back on the first try.
    const { data: merchant, error } = await fetchMerchantForStellarToml(supabase, merchantId);

    if (error) {
      finish("lookup_error");
      logger.error({ merchantId, err: error.message ?? String(error) }, "SEP-0001: failed to fetch merchant");
      return res.status(500).json({ error: "Failed to fetch merchant" });
    }

    if (!merchant) {
      finish("not_found");
      return res.status(404).json({ error: "Merchant not found" });
    }

    // Generate stellar.toml
    const report = generateStellarTomlReport(merchant);
    rejections = report.rejections;
    const tomlContent = report.toml;

    for (const rejection of rejections) {
      if (rejection.field === "SIGNING_KEY" && rejection.reason === "secret_seed") {
        logger.error(
          { field: "SIGNING_KEY" },
          "SEP-0001: SIGNING_KEY is a secret seed; it was NOT published. Rotate it and configure the public key",
        );
      }
    }
    if (rejections.length > 0) {
      logger.warn({ merchantId, rejections }, "SEP-0001: fields omitted or altered by sanitization");
    }

    // Validate generated content
    if (!validateStellarToml(tomlContent)) {
      finish("generation_error");
      logger.error({ merchantId }, "SEP-0001: generated an invalid stellar.toml");
      return res.status(500).json({ error: "Failed to generate valid stellar.toml" });
    }

    finish("success", Buffer.byteLength(tomlContent, "utf8"));

    // Return as text/plain with proper caching headers. SEP-0001 requires
    // CORS so wallets running in browsers can read the file.
    res.set({
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "public, max-age=3600", // Cache for 1 hour
      "Access-Control-Allow-Origin": "*",
      "X-Content-Type-Options": "nosniff",
    });
    res.send(tomlContent);
  } catch (err) {
    finish("generation_error");
    if (err instanceof Sep0001ConfigError) {
      logger.error({ merchantId, field: err.field, code: err.code }, "SEP-0001: invalid server configuration");
      return res.status(500).json({ error: "Failed to generate valid stellar.toml" });
    }
    logger.error({ merchantId, err: err?.message }, "SEP-0001: error generating stellar.toml");
    next(err);
  }
});

export default router;
